package com.lqq.supportflow.knowledge.infrastructure.persistence;
import com.lqq.supportflow.knowledge.domain.*; import java.math.BigDecimal; import java.time.Instant; import java.util.List; import org.springframework.stereotype.Component;
@Component public class MyBatisKnowledgeSearchAuditAdapter implements KnowledgeSearchAuditPort { private final KnowledgeSearchMapper searches; private final KnowledgeSearchCitationMapper citations; public MyBatisKnowledgeSearchAuditAdapter(KnowledgeSearchMapper searches,KnowledgeSearchCitationMapper citations){this.searches=searches;this.citations=citations;} public Long save(Long tenantId,Long knowledgeBaseId,String query,List<KnowledgeCitation> results){Instant now=Instant.now();KnowledgeSearchEntity search=new KnowledgeSearchEntity();search.tenantId=tenantId;search.knowledgeBaseId=knowledgeBaseId;search.queryText=query;search.createdAt=now;searches.insert(search);for(KnowledgeCitation result:results){KnowledgeSearchCitationEntity citation=new KnowledgeSearchCitationEntity();citation.tenantId=tenantId;citation.searchId=search.id;citation.documentId=result.documentId();citation.chunkId=result.chunkId();citation.score=BigDecimal.valueOf(result.score());citation.rankNo=result.rank();citation.createdAt=now;citations.insert(citation);}return search.id;}}
